CREATE TABLE IF NOT EXISTS `message_reads` (
	`message_id` text NOT NULL,
	`user_id` text NOT NULL,
	`read` text NOT NULL
);

CREATE TABLE IF NOT EXISTS `payroll_config` (
	`owner` text PRIMARY KEY NOT NULL,
